const root = document.getElementById('app');
const cfg = window.NOLAN_CONFIG;
const createClient = window.supabase?.createClient;
let sb=null, session=null, profile=null;
const state={page:{type:'tab',tab:'dashboard'},history:[],loading:false,error:null,
 customers:[],properties:[],jobs:[],profiles:[],members:[],tasks:[],timeEntries:[],employeeRates:{},jobCosts:[],estimates:[],estimateItems:[],estimateRevisions:[],changeOrders:[],invoices:[],invoiceItems:[],payments:[],materials:[],reports:[],photos:[],activity:[],notifications:[],customerSearch:'',jobFilter:'all',scheduleDate:new Date(),selectedJob:null};
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(v||0));
const num=v=>Number(v||0); const dateFmt=v=>v?new Date(v).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'—';
const dateInput=v=>v?new Date(v).toISOString().slice(0,10):''; const statusLabel=v=>String(v||'').replaceAll('_',' ').replace(/\b\w/g,x=>x.toUpperCase());
const admin=()=>['admin','manager'].includes(profile?.role); const field=()=>['employee','crew_lead'].includes(profile?.role);
const toast=m=>{const x=document.createElement('div');x.className='toast';x.textContent=m;document.body.appendChild(x);setTimeout(()=>x.remove(),3500)};
const fail=e=>{console.error(e);toast(e?.message||String(e));};
function pageKey(p){return `${p?.type}:${p?.tab||p?.id||''}`}
function navigate(p,{replace=false,pop=false}={}){const cur=state.page;if(!replace&&pageKey(cur)!==pageKey(p))state.history.push(cur);state.page=p;state.error=null;if(!pop)history[replace?'replaceState':'pushState']({nolanPage:p},'',`#${p.type==='tab'?p.tab:p.type+'/'+p.id}`);render();loadForPage().catch(fail)}
function back(){if(state.history.length){const p=state.history.pop();navigate(p,{replace:true});}else navigate({type:'tab',tab:field()?'field':'dashboard'},{replace:true})}
window.addEventListener('popstate',e=>{if(e.state?.nolanPage){state.page=e.state.nolanPage;render();loadForPage().catch(fail)}});
function setView(html){root.innerHTML=html}
function fatal(title,msg,details=''){root.innerHTML=`<div class="fatal-screen"><div class="fatal-card"><div class="eyebrow">NOLAN ELECTRIC</div><h1>${esc(title)}</h1><p>${esc(msg)}</p>${details?`<pre>${esc(details)}</pre>`:''}<button class="btn primary" onclick="location.reload()">Reload App</button></div></div>`}
window.addEventListener('error',e=>{console.error(e.error||e.message);if(root)fatal('App error','The app hit an unexpected error. Your data is still in Supabase.',e.message||'Unknown error')});
window.addEventListener('unhandledrejection',e=>{console.error(e.reason);if(root)fatal('App error','The app could not finish loading. Your data is still in Supabase.',e.reason?.message||String(e.reason))});
function login(){return `<div class="login"><div class="login-card"><img src="nolan-logo-transparent.png"><div class="eyebrow">JOB COMMAND CENTER</div><h1>Nolan Electric</h1><p>Run the work. Know the numbers. Build with confidence.</p><form id="loginForm" class="form"><input name="email" type="email" placeholder="Email" required><input name="password" type="password" placeholder="Password" required><button class="btn primary">Sign In</button></form></div></div>`}
function shell(view){const tabs=field()?['field','jobs']:['dashboard','customers','jobs','schedule','team','financial','notifications'];const names={dashboard:'Dashboard',customers:'Customers',jobs:'Jobs',schedule:'Schedule',team:'Team',financial:'Financial',notifications:'Alerts',field:'My Day'};const p=state.page,active=p.type==='customer'?'customers':p.type==='job'?'jobs':p.type==='estimate'?'jobs':p.type==='invoice'?'jobs':p.tab;return `<div class="app-shell"><header class="app-header"><div class="brand-lockup"><img src="nolan-logo-transparent.png"><div><div class="brand-title">Nolan Electric</div><div class="brand-subtitle">JOB COMMAND CENTER</div><div class="brand-tagline">PLAN <i>•</i> TRACK <i>•</i> BUILD <i>•</i> SUCCEED</div></div></div><div class="header-tools"><button class="icon-btn" id="refresh">↻</button><span class="user-chip"><b>${esc(profile?.full_name||'User')}</b><small>${esc(profile?.role||'')}</small></span><button id="logout" class="btn header-signout">Sign Out</button></div></header><div class="app-layout"><aside class="sidebar"><div class="sidebar-brand">NOLAN ELECTRIC</div>${tabs.map(t=>`<button data-tab="${t}" class="side-nav ${active===t?'active':''}">${names[t]}</button>`).join('')}<div class="sidebar-spacer"></div><div class="trust-mark">MORE THAN POWER<br><b>PEOPLE YOU CAN TRUST</b></div></aside><main class="main-content"><div class="mobile-nav">${tabs.map(t=>`<button data-tab="${t}" class="${active===t?'active':''}">${names[t]}</button>`).join('')}</div>${view}</main></div></div>`}
function render(){try{if(!session){setView(login());return}let view='';const p=state.page;if(p.type==='customer')view=customerPage();else if(p.type==='job')view=jobPage();else if(p.type==='estimate')view=estimatePage();else if(p.type==='invoice')view=invoicePage();else {view=p.tab==='dashboard'?dashboard():p.tab==='customers'?customers():p.tab==='jobs'?jobs():p.tab==='schedule'?schedule():p.tab==='team'?team():p.tab==='financial'?financial():p.tab==='notifications'?notificationsPage():fieldPage()}setView(shell(view))}catch(e){console.error(e);fatal('Screen error','This screen could not be rendered.',e?.message||String(e))}}
function top(title,sub='',backBtn=false,actions=''){return `<div class="page-heading"><div>${backBtn?'<button class="back-link" id="back">← Back</button>':''}<div class="eyebrow">${backBtn?'WORKSPACE':'COMMAND CENTER'}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`}
function metric(label,value,sub=''){return `<div class="metric"><span>${label}</span><b>${value}</b><small>${sub}</small></div>`}
function dashboard(){const active=state.jobs.filter(j=>['approved','scheduled','in_progress','punch_list','complete'].includes(j.status));const open=state.jobs.filter(j=>!['paid','closed'].includes(j.status));const contract=state.jobs.reduce((a,j)=>a+num(j.contract_amount),0);const unpaid=state.invoices.filter(i=>i.status!=='paid').reduce((a,i)=>a+num(i.total)-paymentsFor(i.id),0);return `${top('Good '+(new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening')+', '+esc((profile?.full_name||'Boss').split(' ')[0])+'.','Here is what needs attention across Nolan Electric.','',`<button class="btn primary" id="newJob">+ New Job</button>`)}<div class="metric-grid">${metric('Active Jobs',active.length,`${open.length} jobs still open`)}${metric('Contract Value',money(contract),`${state.jobs.length} total jobs`)}${metric('Outstanding',money(unpaid),'Invoices not fully paid')}${metric('Customers',state.customers.length,'Customer accounts')}</div><div class="dashboard-grid"><section class="card"><div class="section-head"><div><div class="eyebrow">ATTENTION</div><h2>Needs Action</h2></div></div>${attention()}</section><section class="card"><div class="section-head"><div><div class="eyebrow">WORKFLOW</div><h2>Job Pipeline</h2></div><button class="btn" data-tab="jobs">Open Jobs →</button></div><div class="pipeline">${['lead','estimate','approved','scheduled','in_progress','punch_list','complete','invoiced','paid'].map(s=>`<button data-filter="${s}"><b>${state.jobs.filter(j=>j.status===s).length}</b><span>${statusLabel(s)}</span></button>`).join('')}</div></section></div><section class="card"><div class="section-head"><div><div class="eyebrow">RECENT</div><h2>Recent Jobs</h2></div><button class="btn" data-tab="jobs">All Jobs →</button></div>${jobList(state.jobs.slice().sort((a,b)=>new Date(b.updated_at)-new Date(a.updated_at)).slice(0,6))}</section>`}
function attention(){const due=state.invoices.filter(i=>i.status!=='paid'&&i.due_date&&new Date(i.due_date)<new Date());const pendingCO=state.changeOrders.filter(x=>x.status==='draft');const pendingMat=state.materials.filter(x=>!['received','assigned'].includes(x.status));return `<div class="attention-list">${due.length?`<button class="attention-row" data-tab="jobs"><b>⚠ ${due.length} overdue invoice${due.length===1?'':'s'}</b><span>Review billing →</span></button>`:''}${pendingCO.length?`<button class="attention-row" data-tab="jobs"><b>↔ ${pendingCO.length} change order${pendingCO.length===1?'':'s'} awaiting approval</b><span>Review jobs →</span></button>`:''}${pendingMat.length?`<button class="attention-row" data-tab="jobs"><b>▣ ${pendingMat.length} material request${pendingMat.length===1?'':'s'} in purchasing</b><span>Open jobs →</span></button>`:''}${!due.length&&!pendingCO.length&&!pendingMat.length?'<div class="empty">You are caught up. Nice work.</div>':''}</div>`}
function jobList(list){return `<div class="list">${list.length?list.map(j=>`<div class="list-row"><div><b>${esc(j.job_number)} · ${esc(j.name)}</b><div class="sub">${esc(j.customers?.name||'No customer')} · ${statusLabel(j.status)} · ${j.scheduled_start?dateFmt(j.scheduled_start):'Not scheduled'}</div></div><div class="row-actions">${admin()?`<span class="money">${money(j.contract_amount)}</span>`:''}<button class="btn" data-job="${j.id}">Open</button></div></div>`).join(''):'<div class="empty">No jobs found.</div>'}</div>`}
function customers(){const q=state.customerSearch.toLowerCase();const list=state.customers.filter(c=>!q||[c.name,c.company,c.phone,c.email].some(v=>String(v||'').toLowerCase().includes(q)));return `${top('Customers',`${state.customers.length} customer accounts`,'',`<button class="btn primary" id="newCustomer">+ Customer</button>`)}<section class="card"><input id="customerSearch" class="search-input" value="${esc(state.customerSearch)}" placeholder="Search name, company, phone or email…"><div class="customer-grid">${list.length?list.map(c=>{const ps=state.properties.filter(p=>p.customer_id===c.id),js=state.jobs.filter(j=>j.customer_id===c.id);return `<button class="customer-card" data-customer="${c.id}"><div class="row"><div><b>${esc(c.name)}</b><div class="sub">${esc(c.company||'Individual')}</div></div><span class="avatar">${esc((c.name||'?')[0].toUpperCase())}</span></div><div class="customer-contact">${c.phone?`☎ ${esc(c.phone)}`:''} ${c.email?`✉ ${esc(c.email)}`:''}</div><div class="customer-summary"><span><b>${ps.length}</b> sites</span><span><b>${js.length}</b> jobs</span><span><b>${money(js.reduce((a,j)=>a+num(j.contract_amount),0))}</b> contract</span></div></button>`}).join(''):'<div class="empty">No customers match your search.</div>'}</div></section>`}
function customerPage(){const c=state.customers.find(x=>x.id===state.page.id);if(!c)return `${top('Customer not found','','',`<button class="btn" id="back">← Back</button>`)}`;const js=state.jobs.filter(j=>j.customer_id===c.id).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));const ps=state.properties.filter(p=>p.customer_id===c.id);const inv=state.invoices.filter(i=>js.some(j=>j.id===i.job_id));const paid=inv.reduce((a,i)=>a+paymentsFor(i.id),0), billed=inv.reduce((a,i)=>a+num(i.total),0),contract=js.reduce((a,j)=>a+num(j.contract_amount),0);return `${top(esc(c.name),`${esc(c.company||'Individual')} · Customer account`,'back',`<button id="editCustomer" class="btn">Edit</button><button id="addProperty" class="btn primary">+ Property</button><button id="newJobForCustomer" class="btn">+ Job</button>`)}<section class="card hero-card"><div><div class="avatar large">${esc((c.name||'?')[0].toUpperCase())}</div><h2>${esc(c.name)}</h2><p>${esc(c.company||'Individual')}</p><div class="contact-grid"><span>PHONE<br><b>${esc(c.phone||'—')}</b></span><span>EMAIL<br><b>${esc(c.email||'—')}</b></span></div></div><div class="note-box"><b>Customer Notes</b><p>${esc(c.notes||'No notes yet.')}</p></div></section><div class="metric-grid">${metric('Contract Value',money(contract),'All customer jobs')}${metric('Invoiced',money(billed),`${inv.length} invoices`)}${metric('Payments',money(paid),'Recorded payments')}${metric('Balance',money(Math.max(0,billed-paid)),'Outstanding')}</div><div class="two-col"><section class="card"><div class="section-head"><div><div class="eyebrow">JOB SITES</div><h2>Properties</h2></div></div>${ps.length?ps.map(p=>`<div class="property-card"><b>${esc([p.address_line1,p.city,p.state,p.postal_code].filter(Boolean).join(', '))}</b><div class="sub">${js.filter(j=>j.property_id===p.id).length} jobs at this site</div></div>`).join(''):'<div class="empty">No properties yet.</div>'}</section><section class="card"><div class="section-head"><div><div class="eyebrow">WORK HISTORY</div><h2>All Jobs</h2></div></div>${js.length?js.map(j=>`<button class="list-row job-link" data-job="${j.id}"><div><b>${esc(j.job_number)} · ${esc(j.name)}</b><div class="sub">${statusLabel(j.status)} · ${j.property_id&&ps.find(p=>p.id===j.property_id)?esc(ps.find(p=>p.id===j.property_id).address_line1):'No site'}</div></div><b>${money(j.contract_amount)}</b></button>`).join(''):'<div class="empty">No jobs yet.</div>'}</section></div><section class="card"><div class="section-head"><div><div class="eyebrow">ACCOUNT HISTORY</div><h2>Invoices & Payments</h2></div></div>${inv.length?inv.map(i=>`<button class="history-row" data-invoice="${i.id}"><div><b>${esc(i.invoice_number)}</b><small>${statusLabel(i.invoice_type)} · ${statusLabel(i.status)} · Due ${dateFmt(i.due_date)}</small></div><div><b>${money(i.total)}</b><small>${money(paymentsFor(i.id))} paid · ${money(Math.max(0,num(i.total)-paymentsFor(i.id)))} balance</small></div></button>`).join(''):'<div class="empty">No invoices yet.</div>'}</section>`}
function jobs(){let list=state.jobs.slice();if(state.jobFilter!=='all')list=list.filter(j=>j.status===state.jobFilter);return `${top('Jobs',`${state.jobs.length} jobs · ${state.jobFilter==='all'?'all statuses':statusLabel(state.jobFilter)}`,'',`<button class="btn primary" id="newJob">+ New Job</button>`)}<section class="card"><div class="filter-bar"><button class="pill ${state.jobFilter==='all'?'active':''}" data-filter="all">All</button>${['lead','estimate','approved','scheduled','in_progress','punch_list','complete','invoiced','paid','closed'].map(s=>`<button class="pill ${state.jobFilter===s?'active':''}" data-filter="${s}">${statusLabel(s)} <b>${state.jobs.filter(j=>j.status===s).length}</b></button>`).join('')}</div>${jobList(list)}</section>`}
function jobPage(){const j=state.jobs.find(x=>x.id===state.page.id)||state.selectedJob;if(!j)return `${top('Job not found','','',`<button class="btn" id="back">← Back</button>`)}`;state.selectedJob=j;const fieldMode=field();const tasks=state.tasks.filter(t=>t.job_id===j.id),members=state.members.filter(m=>m.job_id===j.id),costs=state.jobCosts.filter(c=>c.job_id===j.id),tes=state.timeEntries.filter(t=>t.job_id===j.id),est=state.estimates.filter(e=>e.job_id===j.id),co=state.changeOrders.filter(x=>x.job_id===j.id),inv=state.invoices.filter(x=>x.job_id===j.id),mat=state.materials.filter(x=>x.job_id===j.id),rep=state.reports.filter(x=>x.job_id===j.id),ph=state.photos.filter(x=>x.job_id===j.id),act=state.activity.filter(x=>x.job_id===j.id).slice(0,12);const actualLabor=tes.reduce((a,t)=>a+(num(t.duration_minutes)/60)*num(state.employeeRates[t.profile_id]),0),actualMat=costs.filter(c=>c.cost_type==='material').reduce((a,c)=>a+num(c.amount),0),actualOther=costs.filter(c=>c.cost_type!=='material').reduce((a,c)=>a+num(c.amount),0),actual=actualLabor+actualMat+actualOther,profit=num(j.contract_amount)-actual,budget=num(j.estimated_labor_cost)+num(j.estimated_material_cost)+num(j.estimated_other_cost);return `${top(`${esc(j.job_number)} · ${esc(j.name)}`,`${esc(j.customers?.name||'No customer')} · ${statusLabel(j.status)}`,'back',`${!fieldMode?`<button id="editJob" class="btn">Edit Job</button>`:''}`)}<section class="job-hero card"><div><div class="eyebrow">JOB OVERVIEW</div><h1>${esc(j.name)}</h1><p>${esc(j.description||'No description')}</p><div class="tag-row"><span class="pill active">${statusLabel(j.status)}</span><span class="pill">${j.scheduled_start?dateFmt(j.scheduled_start):'Unscheduled'}</span><span class="pill">${esc(j.job_type||'Electrical')}</span></div>${admin()?`<div class="status-select"><label>JOB STATUS</label><select id="jobStatus">${['lead','estimate','approved','scheduled','in_progress','punch_list','complete','invoiced','paid','closed'].map(s=>`<option value="${s}" ${j.status===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select></div>`:''}</div>${admin()?`<div class="profit-box"><small>PROJECT PROFIT</small><b>${money(profit)}</b><span>${budget?((profit/num(j.contract_amount||1))*100).toFixed(1):'—'}% gross margin</span></div>`:''}</section><div class="job-kpis">${admin()?metric('Contract',money(j.contract_amount),'Base + approved changes'):''}${metric('Tasks',`${tasks.filter(t=>t.status==='complete').length}/${tasks.length}`,'Completed')}${metric('Field Hours',(tes.reduce((a,t)=>a+num(t.duration_minutes),0)/60).toFixed(1),'Logged hours')}${admin()?metric('Actual Cost',money(actual),`Budget ${money(budget)}`):''}</div><div class="quick-actions">${!fieldMode?`<button class="quick-action" id="openEstimate">Estimate<strong>Build / revise</strong></button><button class="quick-action" id="openChange">Change Order<strong>${co.length} records</strong></button><button class="quick-action" id="openInvoice">Invoice<strong>${inv.length} invoices</strong></button>`:''}<button class="quick-action" id="fieldNote">Note<strong>Add update</strong></button><button class="quick-action" id="materialRequest">Materials<strong>${mat.filter(x=>!['received','assigned'].includes(x.status)).length} pending</strong></button></div>${fieldMode?fieldControls(j,tes):''}<div class="section-grid"><section class="card"><div class="section-head"><div><div class="eyebrow">EXECUTION</div><h2>Tasks & Crew</h2></div>${admin()?'<button id="assignCrew" class="btn">+ Crew</button>':''}</div>${members.length?`<div class="crew-strip">${members.map(m=>`<span class="crew-chip">${esc(m.profiles?.full_name||'Crew')}</span>`).join('')}</div>`:''}${tasks.length?tasks.map(t=>`<div class="task-row"><label><input type="checkbox" data-task="${t.id}" ${t.status==='complete'?'checked':''}><span><b>${esc(t.title)}</b><small>${esc(t.description||'')}${t.assigned_to?' · '+esc(state.profiles.find(p=>p.id===t.assigned_to)?.full_name||'Assigned'):''}</small></span></label>${admin()?`<select data-task-assignee="${t.id}"><option value="">Unassigned</option>${state.profiles.filter(p=>p.active).map(p=>`<option value="${p.id}" ${p.id===t.assigned_to?'selected':''}>${esc(p.full_name)}</option>`).join('')}</select>`:''}</div>`).join(''):'<div class="empty">No tasks.</div>'}</section><section class="card"><div class="section-head"><div><div class="eyebrow">PURCHASING</div><h2>Materials</h2></div>${admin()?'<button id="manageMaterials" class="btn">Manage</button>':''}</div>${materialsMarkup(mat)}</section></div><div class="section-grid"><section class="card"><div class="section-head"><div><div class="eyebrow">DOCUMENTS</div><h2>Estimates · Change Orders · Invoices · Reports</h2></div></div>${changeOrdersMarkup(co)}${documentsMarkup(est,[],inv,rep)}</section><section class="card"><div class="section-head"><div><div class="eyebrow">FIELD RECORD</div><h2>Photos & Daily Reports</h2></div></div>${photosReportsMarkup(ph,rep)}</section></div>${admin()?profitability(j,actualLabor,actualMat,actualOther,budget):''}<section class="card"><div class="section-head"><div><div class="eyebrow">ACTIVITY</div><h2>What Changed</h2></div></div>${activityMarkup(act)}</section></div>`}
function fieldControls(j,tes){const active=tes.find(t=>t.profile_id===session.user.id&&!t.ended_at);return `<section class="field-control card"><div><div class="eyebrow">MY SHIFT</div><h2>${active?'Clock is running':'Ready for work'}</h2><p>${active?'Started '+dateFmt(active.started_at):'Track your time to this job.'}</p></div><div class="row-actions">${active?'<button id="stopTimer" class="btn danger">Stop Clock</button>':'<button id="startTimer" class="btn primary">Clock In</button>'}<button id="logHours" class="btn">Log Hours</button><button id="dailyReport" class="btn">Daily Report</button><button id="addPhoto" class="btn">Photo</button></div></section>`}
function profitability(j,labor,mat,other,budget){const actual=labor+mat+other, variance=actual-budget, margin=num(j.contract_amount)?((num(j.contract_amount)-actual)/num(j.contract_amount)*100):0;return `<section class="card"><div class="section-head"><div><div class="eyebrow">JOB PROFITABILITY</div><h2>Estimated vs Actual</h2></div><span class="pill ${variance>budget*.1?'danger-pill':variance>budget*.05?'warn-pill':'active'}">${budgetState(budget,actual)}</span></div><div class="profit-grid"><div><span>Est. Labor</span><b>${money(j.estimated_labor_cost)}</b><small>Actual ${money(labor)}</small></div><div><span>Est. Materials</span><b>${money(j.estimated_material_cost)}</b><small>Actual ${money(mat)}</small></div><div><span>Est. Other</span><b>${money(j.estimated_other_cost)}</b><small>Actual ${money(other)}</small></div><div><span>Gross Profit</span><b>${money(num(j.contract_amount)-actual)}</b><small>${margin.toFixed(1)}% margin</small></div></div><div class="sub">Current cost ${money(actual)} · Variance ${money(variance)}</div></section>`}
function budgetState(e,a){if(!e)return'No Budget';const p=(a-e)/e*100;return p>10?'Over Budget':p>5?'Watch':'On Budget'}
function materialsMarkup(list){return list.length?list.map(m=>`<div class="material-row"><div><b>${esc(m.item)}</b><small>${m.quantity} · ${esc(m.vendor||'No vendor')} ${m.purchase_order?'· PO '+esc(m.purchase_order):''}</small></div><select data-material-status="${m.id}"><option value="requested" ${m.status==='requested'?'selected':''}>Requested</option><option value="ordered" ${m.status==='ordered'?'selected':''}>Ordered</option><option value="received" ${m.status==='received'?'selected':''}>Received</option><option value="assigned" ${m.status==='assigned'?'selected':''}>Assigned</option></select></div>`).join(''):'<div class="empty">No material requests.</div>'}
function changeOrdersMarkup(list){return `<section class="subsection"><div class="section-head"><div><h3>Change Orders</h3><span class="sub">Approved changes increase contract value and can be billed on new invoices.</span></div><button id="openChange" class="btn primary">+ Change Order</button></div>${list.length?list.map(x=>`<div class="change-row"><div><b>CO-${String(x.change_number).padStart(3,'0')} · ${esc(x.title)}</b><small>${statusLabel(x.status)} · ${money(x.amount)} · ${dateFmt(x.created_at)}</small><p>${esc(x.description||'')}</p></div><div class="row-actions">${x.status==='draft'?`<button class="btn primary" data-co-action="approve" data-co-id="${x.id}">Approve + Contract</button><button class="btn" data-co-action="reject" data-co-id="${x.id}">Reject</button>`:x.status==='approved'?`<button class="btn danger" data-co-action="reject" data-co-id="${x.id}">Reverse</button>`:`<span class="pill">Rejected</span>`}</div></div>`).join(''):'<div class="empty">No change orders yet.</div>'}</section>`}
function documentsMarkup(est,co,inv,rep){return `<div class="doc-grid">${est.map(e=>`<button class="doc-card" data-estimate="${e.id}"><b>EST · ${esc(e.estimate_number)}</b><small>${statusLabel(e.status)} · ${money(e.total)}</small></button>`).join('')}${co.map(x=>`<button class="doc-card" data-change="${x.id}"><b>CO-${String(x.change_number).padStart(3,'0')} · ${esc(x.title)}</b><small>${statusLabel(x.status)} · ${money(x.amount)}</small></button>`).join('')}${inv.map(i=>`<button class="doc-card" data-invoice="${i.id}"><b>${esc(i.invoice_number)}</b><small>${statusLabel(i.invoice_type)} · ${statusLabel(i.status)} · ${money(i.total)}</small></button>`).join('')}${rep.map(r=>`<div class="doc-card"><b>DAILY REPORT · ${dateFmt(r.report_date)}</b><small>${num(r.hours)} hrs · ${esc(r.notes||'')}</small></div>`).join('')}${!est.length&&!co.length&&!inv.length&&!rep.length?'<div class="empty">No documents yet.</div>':''}</div>`}
function photosReportsMarkup(ph,rep){return `<div class="photo-grid">${ph.map(p=>`<div class="photo-card"><img src="${esc(sb.storage.from('job-photos').getPublicUrl(p.storage_path).data.publicUrl)}"><small>${esc(p.caption||'')} · ${dateFmt(p.created_at)}</small></div>`).join('')||'<div class="empty">No job photos yet.</div>'}</div>`}
function activityMarkup(list){return list.length?list.map(a=>`<div class="activity-row"><span class="activity-dot"></span><div><b>${esc(statusLabel(a.event_type))}</b><p>${esc(a.message||'')}</p><small>${dateFmt(a.created_at)}</small></div></div>`).join(''):'<div class="empty">No activity yet.</div>'}
function schedule(){const d=new Date(state.scheduleDate);d.setHours(0,0,0,0);const monday=new Date(d);monday.setDate(d.getDate()-((d.getDay()+6)%7));const days=Array.from({length:7},(_,i)=>{const x=new Date(monday);x.setDate(monday.getDate()+i);return x});const key=x=>x.toISOString().slice(0,10);return `${top('Schedule','Drag jobs to another day. Open a job to assign crew and exact hours.','',`<button id="todaySchedule" class="btn">Today</button><button id="newJob" class="btn primary">+ Job</button>`)}<section class="card"><div class="calendar-grid">${days.map(x=>{const k=key(x),list=state.jobs.filter(j=>dateInput(j.scheduled_start)===k);return `<div class="calendar-day ${k===key(new Date())?'today':''}" data-drop-date="${k}"><div class="day-head"><b>${x.toLocaleDateString('en-US',{weekday:'short'})}</b><span>${x.toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span></div>${list.map(j=>`<div class="calendar-job" draggable="true" data-drag-job="${j.id}"><b>${esc(j.job_number)}</b><span>${esc(j.name)}</span><small>${esc(j.customers?.name||'No customer')}</small></div>`).join('')||'<div class="day-empty">Drop jobs here</div>'}</div>`}).join('')}</div></section><section class="card"><div class="section-head"><h2>Unscheduled</h2><span class="sub">Drag onto a day</span></div><div class="unscheduled">${state.jobs.filter(j=>!j.scheduled_start).map(j=>`<div class="calendar-job" draggable="true" data-drag-job="${j.id}"><b>${esc(j.job_number)}</b><span>${esc(j.name)}</span></div>`).join('')||'<div class="empty">Everything is scheduled.</div>'}</div></section>`}
function team(){return `${top('Team',`${state.profiles.length} people · permissions are role based`,'',`<button id="newEmployee" class="btn primary">+ Employee</button><button id="backup" class="btn">Backup Data</button>`)}<section class="card"><div class="team-grid">${state.profiles.map(p=>`<div class="team-card"><div class="row"><span class="avatar">${esc((p.full_name||'?')[0])}</span><span class="pill ${p.active?'active':''}">${p.active?'Active':'Inactive'}</span></div><h3>${esc(p.full_name)}</h3><p>${esc(p.role)} · ${esc(p.email||'')}</p><p>${esc(p.phone||'')}</p><button class="btn" data-employee="${p.id}">Manage</button></div>`).join('')}</div></section>`}
function financial(){const contract=state.jobs.reduce((a,j)=>a+num(j.contract_amount),0);const billed=state.invoices.reduce((a,i)=>a+num(i.total),0),paid=state.payments.reduce((a,p)=>a+num(p.amount),0);const labor=state.timeEntries.reduce((a,t)=>a+(num(t.duration_minutes)/60)*num(state.employeeRates[t.profile_id]),0),costs=state.jobCosts.reduce((a,c)=>a+num(c.amount),0);return `${top('Financial','Company-level numbers. Employee users never see internal rates or profitability.','','')}<div class="metric-grid">${metric('Contract Value',money(contract),'Active database jobs')}${metric('Invoiced',money(billed),'All invoices')}${metric('Collected',money(paid),'All payments')}${metric('Outstanding',money(Math.max(0,billed-paid)),'Accounts receivable')}</div><div class="two-col"><section class="card"><h2>Actual Cost</h2>${metric('Labor',money(labor),'Time × internal labor rate')}${metric('Materials & Other',money(costs),'Recorded job costs')}${metric('Total Cost',money(labor+costs),'Current actual cost')}</section><section class="card"><h2>Job Profitability</h2>${state.jobs.map(j=>{const ts=state.timeEntries.filter(t=>t.job_id===j.id),cs=state.jobCosts.filter(c=>c.job_id===j.id),c=ts.reduce((a,t)=>a+(num(t.duration_minutes)/60)*num(state.employeeRates[t.profile_id]),0)+cs.reduce((a,x)=>a+num(x.amount),0);return `<button class="list-row" data-job="${j.id}"><div><b>${esc(j.job_number)} · ${esc(j.name)}</b><small>${statusLabel(j.status)}</small></div><b>${money(num(j.contract_amount)-c)}</b></button>`}).join('')}</section></div>`}
function notificationsPage(){const acts=state.activity.slice().sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).slice(0,50);return `${top('Alerts & Activity','Everything that changed, newest first.','',`<button id="markRead" class="btn">Mark Alerts Read</button>`)}<section class="card">${acts.length?activityMarkup(acts):'<div class="empty">No activity yet.</div>'}</section>`}
function fieldPage(){const today=dateInput(new Date());const mine=state.members.filter(m=>m.profile_id===session.user.id).map(m=>m.job_id);const js=state.jobs.filter(j=>mine.includes(j.id)&&(!j.scheduled_start||dateInput(j.scheduled_start)===today));return `${top('My Day','Your assigned work, clock, tasks and field updates.','','')}<section class="card"><h2>Today</h2>${js.length?js.map(j=>`<button class="field-job" data-job="${j.id}"><div><b>${esc(j.job_number)} · ${esc(j.name)}</b><span>${esc(j.customers?.name||'No customer')}</span></div><span class="pill active">${statusLabel(j.status)}</span></button>`).join(''):'<div class="empty">No assigned jobs for today.</div>'}</section><section class="card"><h2>Open Assigned Jobs</h2>${jobList(state.jobs.filter(j=>mine.includes(j.id)))}</section>`}
function estimatePage(){const j=state.jobs.find(x=>x.id===state.page.jobId),e=state.estimates.find(x=>x.id===state.page.id),items=state.estimateItems.filter(x=>x.estimate_id===e.id),revs=state.estimateRevisions.filter(x=>x.estimate_id===e.id);return `${top(`Estimate ${esc(e.estimate_number)}`,`${esc(j?.name||'Job')} · ${statusLabel(e.status)}`,'back',`<button id="editEstimatePage" class="btn">Edit</button><button id="printEstimate" class="btn primary">Print / PDF</button>`)}<section class="card estimate-paper"><div class="row"><div><h2>${esc(e.estimate_number)}</h2><p>${esc(j?.customers?.name||'Customer')}</p></div><span class="pill active">${statusLabel(e.status)}</span></div><table><thead><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Amount</th></tr></thead><tbody>${items.map(x=>`<tr><td><b>${esc(x.description)}</b><small>${esc(x.category||'')}</small></td><td>${x.quantity}</td><td>${money(x.sell_price)}</td><td>${money(num(x.quantity)*num(x.sell_price))}</td></tr>`).join('')}</tbody></table><div class="totals"><div>Subtotal <b>${money(e.subtotal)}</b></div><div>Tax <b>${money(e.tax)}</b></div><div class="grand">Total <b>${money(e.total)}</b></div></div><p>${esc(e.notes||'')}</p></section><section class="card"><div class="section-head"><h2>Revision History</h2><span class="sub">${revs.length} revisions</span></div>${revs.map(r=>`<div class="history-row"><div><b>Revision ${r.revision_number}</b><small>${dateFmt(r.created_at)} · ${esc(r.notes||'')}</small></div></div>`).join('')||'<div class="empty">No prior revisions. The first save becomes the baseline.</div>'}</section>`}
function invoicePage(){const i=state.invoices.find(x=>x.id===state.page.id),j=state.jobs.find(x=>x.id===i.job_id),items=state.invoiceItems.filter(x=>x.invoice_id===i.id),pays=state.payments.filter(x=>x.invoice_id===i.id),paid=pays.reduce((a,p)=>a+num(p.amount),0);return `${top(`${esc(i.invoice_number)}`,`${statusLabel(i.invoice_type)} · ${esc(j?.name||'Job')} · ${statusLabel(i.status)}`,'back',`<button id="printInvoicePage" class="btn">Print / PDF</button>${admin()?`<button id="recordPayment" class="btn primary">+ Payment</button>`:''}`)}<section class="card invoice-paper"><div class="invoice-head"><div><h2>Nolan Electric</h2><p>${esc(j?.customers?.name||'Customer')}</p></div><span class="invoice-status">${statusLabel(i.status)}</span></div><div class="invoice-meta"><span>TYPE<b>${statusLabel(i.invoice_type)}</b></span><span>DUE<b>${dateFmt(i.due_date)}</b></span><span>TOTAL<b>${money(i.total)}</b></span><span>BALANCE<b>${money(Math.max(0,num(i.total)-paid))}</b></span></div><table><thead><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Amount</th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(x.description)}</td><td>${x.quantity}</td><td>${money(x.unit_price)}</td><td>${money(x.amount)}</td></tr>`).join('')}</tbody></table><div class="totals"><div>Subtotal <b>${money(i.subtotal)}</b></div><div>Tax <b>${money(i.tax)}</b></div><div class="grand">Total <b>${money(i.total)}</b></div><div>Paid <b>${money(paid)}</b></div><div class="balance">Balance <b>${money(Math.max(0,num(i.total)-paid))}</b></div></div><p>${esc(i.memo||'')}</p></section><section class="card"><div class="section-head"><h2>Payment History</h2></div>${pays.length?pays.map(p=>`<div class="history-row"><div><b>${money(p.amount)}</b><small>${dateFmt(p.payment_date)} · ${esc(p.method||'')} ${p.reference?'· '+esc(p.reference):''}</small></div></div>`).join(''):'<div class="empty">No payments recorded.</div>'}</section>`}
function paymentsFor(id){return state.payments.filter(p=>p.invoice_id===id).reduce((a,p)=>a+num(p.amount),0)}
function modal(title,body,onSubmit){const wrap=document.createElement('div');wrap.className='modal';wrap.innerHTML=`<div class="modal-sheet"><div class="modal-head"><h2>${title}</h2><button class="btn" data-close>Close</button></div>${body}</div>`;document.body.appendChild(wrap);wrap.querySelector('[data-close]').onclick=()=>wrap.remove();const form=wrap.querySelector('form');if(form)form.onsubmit=async e=>{e.preventDefault();const btn=form.querySelector('button[type=submit]');if(btn)btn.disabled=true;try{const r=await onSubmit(new FormData(form));if(r?.error)throw r.error;wrap.remove();await loadForPage();toast('Saved.')}catch(err){fail(err);if(btn)btn.disabled=false}};return wrap}
function customerForm(c){return modal(c?'Edit Customer':'New Customer',`<form class="form"><input name="name" value="${esc(c?.name||'')}" placeholder="Customer name" required><input name="company" value="${esc(c?.company||'')}" placeholder="Company"><input name="phone" value="${esc(c?.phone||'')}" placeholder="Phone"><input name="email" type="email" value="${esc(c?.email||'')}" placeholder="Email"><textarea name="notes" placeholder="Customer notes">${esc(c?.notes||'')}</textarea><button class="btn primary" type="submit">Save Customer</button></form>`,async f=>c?sb.from('customers').update({name:f.get('name'),company:f.get('company'),phone:f.get('phone'),email:f.get('email'),notes:f.get('notes')}).eq('id',c.id):sb.from('customers').insert({name:f.get('name'),company:f.get('company'),phone:f.get('phone'),email:f.get('email'),notes:f.get('notes')}))}
function propertyForm(c){return modal('Add Property',`<form class="form"><p class="sub">Site for ${esc(c.name)}</p><input name="address_line1" placeholder="Street address" required><input name="city" placeholder="City"><input name="state" value="GA" placeholder="State"><input name="postal_code" placeholder="ZIP"><button class="btn primary" type="submit">Save Property</button></form>`,f=>sb.from('properties').insert({customer_id:c.id,address_line1:f.get('address_line1'),city:f.get('city'),state:f.get('state'),postal_code:f.get('postal_code')}))}
function jobForm(j=null,customerId=null){const customers=state.customers, props=state.properties.filter(p=>p.customer_id===j?.customer_id||p.customer_id===customerId);return modal(j?'Edit Job':'New Job',`<form class="form"><input name="name" value="${esc(j?.name||'')}" placeholder="Job name" required><select name="customer_id" required><option value="">Customer</option>${customers.map(c=>`<option value="${c.id}" ${c.id===(j?.customer_id||customerId)?'selected':''}>${esc(c.name)}${c.company?' · '+esc(c.company):''}</option>`).join('')}</select><select name="property_id"><option value="">No property / job site</option>${props.map(p=>`<option value="${p.id}" ${p.id===j?.property_id?'selected':''}>${esc(p.address_line1)}</option>`).join('')}</select><select name="job_type"><option>Service</option><option>Residential</option><option>Commercial</option><option>Industrial</option><option>Solar</option><option>New Build</option><option>Other</option></select><textarea name="description" placeholder="Scope / notes">${esc(j?.description||'')}</textarea><div class="form-grid"><input name="contract_amount" type="number" step=".01" value="${num(j?.contract_amount)}" placeholder="Contract"><input name="estimated_labor_hours" type="number" step=".25" value="${num(j?.estimated_labor_hours)}" placeholder="Labor hours"><input name="estimated_labor_cost" type="number" step=".01" value="${num(j?.estimated_labor_cost)}" placeholder="Labor budget"><input name="estimated_material_cost" type="number" step=".01" value="${num(j?.estimated_material_cost)}" placeholder="Material budget"><input name="estimated_other_cost" type="number" step=".01" value="${num(j?.estimated_other_cost)}" placeholder="Other budget"></div><select name="status">${['lead','estimate','approved','scheduled','in_progress','punch_list','complete','invoiced','paid','closed'].map(s=>`<option value="${s}" ${j?.status===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select><button class="btn primary" type="submit">Save Job</button></form>`,async f=>{const data={name:f.get('name'),customer_id:f.get('customer_id')||null,property_id:f.get('property_id')||null,job_type:f.get('job_type'),description:f.get('description'),contract_amount:num(f.get('contract_amount')),estimated_labor_hours:num(f.get('estimated_labor_hours')),estimated_labor_cost:num(f.get('estimated_labor_cost')),estimated_material_cost:num(f.get('estimated_material_cost')),estimated_other_cost:num(f.get('estimated_other_cost')),status:f.get('status'),updated_at:new Date().toISOString()};if(j)return sb.from('jobs').update(data).eq('id',j.id);const next='NE-'+new Date().getFullYear()+'-'+String(state.jobs.length+1);const r=await sb.from('jobs').insert({job_number:next,...data}).select().single();if(r.error)return r;const templates=['Site prep / verify scope','Rough-in','Install equipment / devices','Trim / finish','Test & inspect','Punch list / closeout'];await sb.from('job_tasks').insert(templates.map(title=>({job_id:r.data.id,title,status:'open'})));return r})}
function estimateEditor(j,e=null){const items=e?state.estimateItems.filter(x=>x.estimate_id===e.id):[];let rows=items.length?items.map((x,i)=>line(i,x)).join(''):line(0);return modal(e?'Revise Estimate':'Build Estimate',`<form id="estimateForm" class="form"><div class="form-grid"><input name="estimate_number" value="${esc(e?.estimate_number||'EST-'+new Date().getFullYear()+'-'+String(state.estimates.length+1).padStart(3,'0'))}" required><select name="status"><option value="draft">Draft</option><option value="sent">Sent</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select></div><div id="estimateLines">${rows}</div><button type="button" class="btn" id="addEstimateLine">+ Line Item</button><div class="form-grid"><input name="tax" type="number" step=".01" value="${num(e?.tax)}" placeholder="Tax"><input name="notes" value="${esc(e?.notes||'')}" placeholder="Notes / terms"></div><button class="btn primary" type="submit">Save Estimate</button></form>`,async f=>{const rows=[...f.keys()].filter(k=>/^desc_\d+$/.test(k)).map(k=>k.split('_')[1]).map(i=>({description:String(f.get('desc_'+i)||''),quantity:num(f.get('qty_'+i)),sell_price:num(f.get('price_'+i)),unit_cost:num(f.get('cost_'+i)),category:String(f.get('cat_'+i)||'Electrical')})).filter(x=>x.description&&x.quantity>0);let r;if(e){const snap={estimate:e,items:state.estimateItems.filter(x=>x.estimate_id===e.id)};const rev=(await sb.from('estimate_revisions').select('revision_number').eq('estimate_id',e.id).order('revision_number',{ascending:false}).limit(1)).data?.[0]?.revision_number||0;const rr=await sb.from('estimate_revisions').insert({estimate_id:e.id,revision_number:rev+1,snapshot:snap,notes:'Revision before edit',created_by:session.user.id});if(rr.error)return rr;r=await sb.from('estimates').update({estimate_number:f.get('estimate_number'),status:f.get('status'),tax:num(f.get('tax')),notes:f.get('notes'),updated_at:new Date().toISOString()}).eq('id',e.id).select().single();if(r.error)return r;await sb.from('estimate_items').delete().eq('estimate_id',e.id)}else r=await sb.from('estimates').insert({job_id:j.id,estimate_number:f.get('estimate_number'),status:f.get('status'),subtotal:0,tax:num(f.get('tax')),total:0,notes:f.get('notes')}).select().single();if(r.error)return r;const id=e?.id||r.data.id;if(rows.length){const ir=await sb.from('estimate_items').insert(rows.map(x=>({estimate_id:id,...x})));if(ir.error)return ir}const subtotal=rows.reduce((a,x)=>a+x.quantity*x.sell_price,0);return sb.from('estimates').update({subtotal,total:subtotal+num(f.get('tax')),updated_at:new Date().toISOString()}).eq('id',id)});function line(i,x={}){return `<div class="estimate-line"><input name="desc_${i}" value="${esc(x.description||'')}" placeholder="Description" required><input name="qty_${i}" type="number" step=".01" value="${num(x.quantity)||1}" placeholder="Qty"><input name="price_${i}" type="number" step=".01" value="${num(x.sell_price)}" placeholder="Sell price"><input name="cost_${i}" type="number" step=".01" value="${num(x.unit_cost)}" placeholder="Unit cost"><input name="cat_${i}" value="${esc(x.category||'Electrical')}" placeholder="Category"></div>`}}
function changeOrderForm(j){return modal('New Change Order',`<form class="form"><input name="title" placeholder="Change order title" required><textarea name="description" placeholder="Scope / reason"></textarea><input name="amount" type="number" step=".01" min="0" placeholder="Amount" required><button class="btn primary" type="submit">Create Change Order</button></form>`,async f=>{const max=Math.max(0,...state.changeOrders.filter(x=>x.job_id===j.id).map(x=>x.change_number));return sb.from('change_orders').insert({job_id:j.id,change_number:max+1,title:f.get('title'),description:f.get('description'),amount:num(f.get('amount')),status:'draft'}).select().single()})}
function invoiceEditor(j){const approved=state.changeOrders.filter(x=>x.job_id===j.id&&x.status==='approved');const base=state.estimates.find(e=>e.job_id===j.id&&e.status==='approved')||state.estimates.find(e=>e.job_id===j.id);const baseItems=base?state.estimateItems.filter(x=>x.estimate_id===base.id):[];const defaults=baseItems.length?baseItems:approved.map(x=>({description:`Change Order CO-${String(x.change_number).padStart(3,'0')}: ${x.title}`,quantity:1,sell_price:num(x.amount),category:'Change Order'}));return modal('Create Invoice',`<form id="invoiceForm" class="form"><div class="form-grid"><select name="invoice_type"><option value="deposit">Deposit</option><option value="progress">Progress</option><option value="final" selected>Final</option><option value="standard">Standard</option></select><input name="invoice_number" value="INV-${new Date().getFullYear()}-${String(state.invoices.length+1).padStart(3,'0')}" required></div><div id="invoiceLines">${defaults.length?defaults.map((x,i)=>invoiceLine(i,x)).join(''):invoiceLine(0,{description:j.name,quantity:1,sell_price:num(j.contract_amount),category:'Contract'})}</div><button type="button" class="btn" id="addInvoiceLine">+ Line Item</button><div class="form-grid"><input name="tax" type="number" step=".01" value="0" placeholder="Tax"><input name="due_date" type="date" value="${dateInput(Date.now()+14*86400000)}"><input name="payment_terms" value="Net 14" placeholder="Payment terms"><input name="deposit_percent" type="number" step=".01" min="0" max="100" placeholder="Deposit % (optional)"></div><textarea name="memo" placeholder="Invoice memo"></textarea><button class="btn primary" type="submit">Create Invoice</button></form>`,async f=>{const rows=[...f.keys()].filter(k=>/^idesc_\d+$/.test(k)).map(k=>k.split('_')[1]).map(i=>({description:String(f.get('idesc_'+i)||''),quantity:num(f.get('iqty_'+i)),unit_price:num(f.get('iprice_'+i)),amount:num(f.get('iqty_'+i))*num(f.get('iprice_'+i)),category:String(f.get('icat_'+i)||'General')})).filter(x=>x.description&&x.quantity>0);const tax=num(f.get('tax')),subtotal=rows.reduce((a,x)=>a+x.amount,0),r=await sb.from('invoices').insert({job_id:j.id,invoice_number:f.get('invoice_number'),invoice_type:f.get('invoice_type'),status:'draft',subtotal,tax,total:subtotal+tax,due_date:f.get('due_date'),payment_terms:f.get('payment_terms'),memo:f.get('memo')}).select().single();if(r.error)return r;const ir=await sb.from('invoice_items').insert(rows.map(x=>({invoice_id:r.data.id,...x})));if(ir.error)return ir;return sb.from('jobs').update({updated_at:new Date().toISOString()}).eq('id',j.id)});function invoiceLine(i,x={}){return `<div class="estimate-line invoice-line"><input name="idesc_${i}" value="${esc(x.description||'')}" placeholder="Description" required><input name="iqty_${i}" type="number" step=".01" value="${num(x.quantity)||1}" placeholder="Qty"><input name="iprice_${i}" type="number" step=".01" value="${num(x.sell_price||x.unit_price)}" placeholder="Unit price"><input name="icat_${i}" value="${esc(x.category||'General')}" placeholder="Category"></div>`}}
function paymentForm(i){const balance=Math.max(0,num(i.total)-paymentsFor(i.id));return modal('Record Payment',`<form class="form"><div class="sub">Invoice ${esc(i.invoice_number)} · Remaining ${money(balance)}</div><input name="amount" type="number" min=".01" max="${balance}" step=".01" value="${balance}" required><input name="payment_date" type="date" value="${dateInput(new Date())}" required><select name="method"><option>Check</option><option>ACH</option><option>Card</option><option>Cash</option><option>Other</option></select><input name="reference" placeholder="Check # / confirmation"><textarea name="notes" placeholder="Notes"></textarea><button class="btn primary" type="submit">Record Payment</button></form>`,async f=>{const r=await sb.from('payments').insert({invoice_id:i.id,amount:num(f.get('amount')),payment_date:f.get('payment_date'),method:f.get('method'),reference:f.get('reference'),notes:f.get('notes')});if(r.error)return r;const sum=paymentsFor(i.id)+num(f.get('amount'));return sb.from('invoices').update({status:sum>=num(i.total)?'paid':'sent',paid_at:sum>=num(i.total)?new Date().toISOString():null}).eq('id',i.id)})}
function dailyReportForm(j){return modal('Daily Report',`<form class="form"><input name="report_date" type="date" value="${dateInput(new Date())}" required><input name="hours" type="number" step=".25" min="0" placeholder="Hours on site" required><textarea name="notes" placeholder="Work completed, issues, next steps" required></textarea><button class="btn primary" type="submit">Submit Report</button></form>`,f=>sb.from('daily_reports').insert({job_id:j.id,submitted_by:session.user.id,report_date:f.get('report_date'),hours:num(f.get('hours')),notes:f.get('notes')}))}
function employeeForm(p){return modal(p?'Manage Employee':'Add Employee',`<form class="form"><input name="full_name" value="${esc(p?.full_name||'')}" placeholder="Full name" required><input name="email" value="${esc(p?.email||'')}" type="email" ${p?'readonly':'required'} placeholder="Email"><input name="phone" value="${esc(p?.phone||'')}" placeholder="Phone"><select name="role">${['employee','crew_lead','manager','admin'].map(r=>`<option value="${r}" ${p?.role===r?'selected':''}>${statusLabel(r)}</option>`).join('')}</select>${p?`<input name="rate" type="number" step=".01" value="${num(state.employeeRates[p.id])}" placeholder="Internal labor cost / hr"><label class="check"><input name="active" type="checkbox" ${p.active?'checked':''}> Active</label>`:''}<button class="btn primary" type="submit">Save</button></form>`,async f=>{if(p){const r=await sb.functions.invoke('employee-admin',{body:{action:'update',id:p.id,full_name:f.get('full_name'),phone:f.get('phone'),role:f.get('role'),active:f.get('active')==='on'}});if(r.error)return r;const rr=await sb.from('employee_labor_rates').upsert({profile_id:p.id,labor_cost_rate:num(f.get('rate')),updated_at:new Date().toISOString()});return rr}const r=await sb.functions.invoke('employee-admin',{body:{action:'create',full_name:f.get('full_name'),email:f.get('email'),phone:f.get('phone'),role:f.get('role')}});if(r.error)return r;if(r.data?.temporary_password)toast(`Employee created. Temporary password: ${r.data.temporary_password}`);return r})}
function crewForm(j){const used=new Set(state.members.filter(x=>x.job_id===j.id).map(x=>x.profile_id));const avail=state.profiles.filter(p=>p.active&&!used.has(p.id));return modal('Assign Crew',`<form class="form"><select name="profile_id">${avail.map(p=>`<option value="${p.id}">${esc(p.full_name)} · ${esc(p.role)}</option>`).join('')}</select><button class="btn primary" type="submit">Assign</button></form>`,f=>sb.from('job_members').insert({job_id:j.id,profile_id:f.get('profile_id')}))}
async function addPhoto(j){const w=modal('Job Photo',`<form class="form"><input name="file" type="file" accept="image/*" capture="environment" required><input name="caption" placeholder="Caption"><button class="btn primary" type="submit">Upload</button></form>`,async f=>{const file=w.querySelector('input[name=file]').files[0];const path=`${j.id}/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await sb.storage.from('job-photos').upload(path,file);if(up.error)return up;return sb.from('job_photos').insert({job_id:j.id,uploaded_by:session.user.id,storage_path:path,caption:f.get('caption')})});return w}
async function loadCore(){
 state.loading=true;
 const safe=async(label,fn,fallback=[])=>{try{const r=await fn;if(r.error){console.warn('Nolan load failed:',label,r.error);return fallback}return r.data||fallback}catch(e){console.warn('Nolan load failed:',label,e);return fallback}};
 [state.customers,state.properties,state.jobs,state.profiles,state.estimates,state.estimateItems,state.estimateRevisions,state.changeOrders,state.invoices,state.invoiceItems,state.payments,state.materials,state.timeEntries,state.jobCosts,state.reports,state.photos,state.activity,state.notifications]=await Promise.all([
  safe('customers',sb.from('customers').select('*').order('name')),
  safe('properties',sb.from('properties').select('*')),
  safe('jobs',sb.from('jobs').select('*,customers(name,company)').order('updated_at',{ascending:false})),
  safe('profiles',sb.from('profiles').select('*').order('full_name')),
  safe('estimates',sb.from('estimates').select('*').order('created_at',{ascending:false})),
  safe('estimate items',sb.from('estimate_items').select('*').order('created_at')),
  safe('estimate revisions',sb.from('estimate_revisions').select('*').order('created_at',{ascending:false})),
  safe('change orders',sb.from('change_orders').select('*').order('created_at',{ascending:false})),
  safe('invoices',sb.from('invoices').select('*').order('created_at',{ascending:false})),
  safe('invoice items',sb.from('invoice_items').select('*').order('created_at')),
  safe('payments',sb.from('payments').select('*').order('payment_date',{ascending:false})),
  safe('materials',sb.from('material_requests').select('*').order('created_at',{ascending:false})),
  safe('time entries',sb.from('time_entries').select('*').order('started_at',{ascending:false})),
  safe('job costs',sb.from('job_costs').select('*').order('cost_date',{ascending:false})),
  safe('daily reports',sb.from('daily_reports').select('*').order('report_date',{ascending:false})),
  safe('photos',sb.from('job_photos').select('*').order('created_at',{ascending:false})),
  safe('activity',sb.from('job_activity').select('*').order('created_at',{ascending:false})),
  safe('notifications',sb.from('notifications').select('*').order('created_at',{ascending:false}))
 ]);
 const rates=admin()?await safe('labor rates',sb.from('employee_labor_rates').select('*')):[];
 state.employeeRates=Object.fromEntries(rates.map(x=>[x.profile_id,num(x.labor_cost_rate)]));
}
async function loadJobExtras(id){const q=async(fn)=>{const r=await fn;if(r.error)throw r.error;return r.data||[]};[state.members,state.tasks]=await Promise.all([q(sb.from('job_members').select('*,profiles(full_name,role)').eq('job_id',id)),q(sb.from('job_tasks').select('*').eq('job_id',id).order('created_at'))])}
async function loadForPage(){if(!sb||!session)return;try{await loadCore();if(state.page.type==='job')await loadJobExtras(state.page.id);if(state.page.type==='estimate'){const e=state.estimates.find(x=>x.id===state.page.id);if(e)state.page.jobId=e.job_id}render()}catch(e){state.error=e.message;render();fail(e)}finally{state.loading=false}}
function backup(){const payload={exported_at:new Date().toISOString(),customers:state.customers,properties:state.properties,jobs:state.jobs,profiles:state.profiles,estimates:state.estimates,estimateItems:state.estimateItems,estimateRevisions:state.estimateRevisions,changeOrders:state.changeOrders,invoices:state.invoices,invoiceItems:state.invoiceItems,payments:state.payments,materials:state.materials,timeEntries:state.timeEntries,jobCosts:state.jobCosts,reports:state.reports,activity:state.activity};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download=`nolan-electric-backup-${dateInput(new Date())}.json`;a.click();URL.revokeObjectURL(a.href)}
function printSimple(title,body){const w=window.open('','_blank');if(!w)return toast('Allow pop-ups to print.');w.document.write(`<html><head><title>${esc(title)}</title><style>body{font-family:Arial;color:#111;margin:0}.page{max-width:850px;margin:auto}.head{background:#111;color:#fff;border-bottom:6px solid #ffe500;padding:25px}.head img{width:75px}.body{padding:30px}table{width:100%;border-collapse:collapse}th{background:#111;color:#fff;text-align:left;padding:10px}td{padding:10px;border-bottom:1px solid #ddd}.totals{margin:20px 0 0 auto;width:300px}.totals div{display:flex;justify-content:space-between;padding:8px}.grand{font-size:20px;font-weight:900;background:#eee}</style></head><body><div class="page"><div class="head"><img src="nolan-logo-transparent.png"><h1>Nolan Electric</h1></div><div class="body">${body}</div></div><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function printEstimatePage(){const e=state.estimates.find(x=>x.id===state.page.id),j=state.jobs.find(x=>x.id===e.job_id),items=state.estimateItems.filter(x=>x.estimate_id===e.id);printSimple(`Estimate ${e.estimate_number}`,`<h1>ESTIMATE</h1><p><b>${esc(e.estimate_number)}</b> · ${esc(j?.customers?.name||'Customer')}</p><h2>${esc(j?.name||'Job')}</h2><table><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Amount</th></tr>${items.map(x=>`<tr><td>${esc(x.description)}</td><td>${x.quantity}</td><td>${money(x.sell_price)}</td><td>${money(num(x.quantity)*num(x.sell_price))}</td></tr>`).join('')}</table><div class="totals"><div>Subtotal <b>${money(e.subtotal)}</b></div><div>Tax <b>${money(e.tax)}</b></div><div class="grand">Total <b>${money(e.total)}</b></div></div><p>${esc(e.notes||'')}</p>`)}
function printInvoicePage(){const i=state.invoices.find(x=>x.id===state.page.id),j=state.jobs.find(x=>x.id===i.job_id),items=state.invoiceItems.filter(x=>x.invoice_id===i.id),paid=paymentsFor(i.id);printSimple(`Invoice ${i.invoice_number}`,`<h1>INVOICE</h1><p><b>${esc(i.invoice_number)}</b> · ${statusLabel(i.invoice_type)} · ${statusLabel(i.status)}</p><p>Bill To: <b>${esc(j?.customers?.name||'Customer')}</b></p><h2>${esc(j?.name||'Job')}</h2><table><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Amount</th></tr>${items.map(x=>`<tr><td>${esc(x.description)}</td><td>${x.quantity}</td><td>${money(x.unit_price)}</td><td>${money(x.amount)}</td></tr>`).join('')}</table><div class="totals"><div>Subtotal <b>${money(i.subtotal)}</b></div><div>Tax <b>${money(i.tax)}</b></div><div class="grand">Total <b>${money(i.total)}</b></div><div>Paid <b>${money(paid)}</b></div><div>Balance <b>${money(Math.max(0,num(i.total)-paid))}</b></div></div><p>${esc(i.memo||'')}</p>`)}
// delegated UI
 document.addEventListener('click',async e=>{try{
 const tab=e.target.closest('[data-tab]');if(tab){state.jobFilter='all';navigate({type:'tab',tab:tab.dataset.tab});return}
 if(e.target.id==='logout'){await sb.auth.signOut();return} if(e.target.id==='refresh'){await loadForPage();return} if(e.target.id==='back'){back();return}
 const cust=e.target.closest('[data-customer]');if(cust){navigate({type:'customer',id:cust.dataset.customer});return}
 const jb=e.target.closest('[data-job]');if(jb){navigate({type:'job',id:jb.dataset.job});return}
 const inv=e.target.closest('[data-invoice]');if(inv){navigate({type:'invoice',id:inv.dataset.invoice});return}
 const est=e.target.closest('[data-estimate]');if(est){navigate({type:'estimate',id:est.dataset.estimate});return}
 if(e.target.id==='newCustomer'){customerForm();return} if(e.target.id==='editCustomer'){customerForm(state.customers.find(x=>x.id===state.page.id));return}
 if(e.target.id==='addProperty'){propertyForm(state.customers.find(x=>x.id===state.page.id));return}
 if(e.target.id==='newJob'||e.target.id==='scheduleNewJob'){jobForm();return}
 if(e.target.id==='newJobForCustomer'){jobForm(null,state.page.id);return}
 if(e.target.id==='editJob'){jobForm(state.jobs.find(x=>x.id===state.page.id));return}
 if(e.target.id==='openEstimate'){const j=state.jobs.find(x=>x.id===state.page.id);const e0=state.estimates.find(x=>x.job_id===j.id);if(e0)navigate({type:'estimate',id:e0.id});else estimateEditor(j);return}
 if(e.target.id==='editEstimatePage'){const e0=state.estimates.find(x=>x.id===state.page.id),j=state.jobs.find(x=>x.id===e0.job_id);estimateEditor(j,e0);return}
 if(e.target.id==='printEstimate'){printEstimatePage();return}
 if(e.target.id==='openChange'){changeOrderForm(state.jobs.find(x=>x.id===state.page.id));return}
 if(e.target.id==='openInvoice'){invoiceEditor(state.jobs.find(x=>x.id===state.page.id));return}
 if(e.target.id==='printInvoicePage'){printInvoicePage();return}
 if(e.target.id==='recordPayment'){paymentForm(state.invoices.find(x=>x.id===state.page.id));return}
 if(e.target.id==='assignCrew'){crewForm(state.jobs.find(x=>x.id===state.page.id));return}
 if(e.target.id==='materialRequest'||e.target.id==='fieldNote'){const j=state.jobs.find(x=>x.id===state.page.id);if(e.target.id==='materialRequest')modal('Material Request',`<form class="form"><input name="item" placeholder="Material" required><input name="quantity" type="number" value="1" step=".01"><input name="vendor" placeholder="Vendor"><input name="unit_cost" type="number" step=".01" placeholder="Unit cost"><textarea name="notes" placeholder="Notes"></textarea><button class="btn primary" type="submit">Request</button></form>`,f=>sb.from('material_requests').insert({job_id:j.id,requested_by:session.user.id,item:f.get('item'),quantity:num(f.get('quantity')),vendor:f.get('vendor'),unit_cost:num(f.get('unit_cost')),total_cost:num(f.get('unit_cost'))*num(f.get('quantity')),notes:f.get('notes'),status:'requested'}));else modal('Field Note',`<form class="form"><textarea name="message" placeholder="What happened?" required></textarea><button class="btn primary" type="submit">Save Note</button></form>`,f=>sb.from('job_activity').insert({job_id:j.id,profile_id:session.user.id,event_type:'field_note',message:f.get('message')}));return}
 if(e.target.id==='startTimer'){const running=state.timeEntries.find(x=>x.profile_id===session.user.id&&!x.ended_at);if(running)return toast('You already have a clock running.');const r=await sb.from('time_entries').insert({job_id:state.page.id,profile_id:session.user.id,started_at:new Date().toISOString()});if(r.error)throw r.error;await loadForPage();return}
 if(e.target.id==='stopTimer'){const t=state.timeEntries.find(x=>x.profile_id===session.user.id&&!x.ended_at&&x.job_id===state.page.id);if(!t)return toast('No active clock on this job.');const end=new Date(),mins=Math.max(1,Math.round((end-new Date(t.started_at))/60000));const r=await sb.from('time_entries').update({ended_at:end.toISOString(),duration_minutes:mins}).eq('id',t.id);if(r.error)throw r.error;await loadForPage();return}
 if(e.target.id==='logHours'){modal('Log Hours',`<form class="form"><input name="hours" type="number" step=".25" min=".25" placeholder="Hours" required><textarea name="notes" placeholder="Notes"></textarea><button class="btn primary" type="submit">Save</button></form>`,f=>sb.from('time_entries').insert({job_id:state.page.id,profile_id:session.user.id,started_at:new Date().toISOString(),ended_at:new Date().toISOString(),duration_minutes:Math.round(num(f.get('hours'))*60),notes:f.get('notes')}));return}
 if(e.target.id==='dailyReport'){dailyReportForm(state.jobs.find(x=>x.id===state.page.id));return}
 if(e.target.id==='addPhoto'){addPhoto(state.jobs.find(x=>x.id===state.page.id));return}
 if(e.target.id==='manageMaterials'){toast('Use the material status controls above; purchasing workflow is built into each request.');return}
 if(e.target.id==='newEmployee'){employeeForm();return} if(e.target.closest('[data-employee]')){employeeForm(state.profiles.find(x=>x.id===e.target.closest('[data-employee]').dataset.employee));return}
 if(e.target.id==='backup'){backup();return}
 const filter=e.target.closest('[data-filter]');if(filter){state.jobFilter=filter.dataset.filter;navigate({type:'tab',tab:'jobs'});return}
 if(e.target.id==='todaySchedule'){state.scheduleDate=new Date();render();return}
 if(e.target.id==='markRead'){toast('Activity is retained as the audit trail.');return}
 }catch(err){fail(err)}});
document.addEventListener('change',async e=>{try{if(e.target.dataset.task){const r=await sb.from('job_tasks').update({status:e.target.checked?'complete':'open',completed_at:e.target.checked?new Date().toISOString():null}).eq('id',e.target.dataset.task);if(r.error)throw r.error;await loadForPage()}else if(e.target.dataset.taskAssignee){const r=await sb.from('job_tasks').update({assigned_to:e.target.value||null}).eq('id',e.target.dataset.taskAssignee);if(r.error)throw r.error;await loadForPage()}else if(e.target.dataset.materialStatus){const status=e.target.value,patch={status};if(status==='ordered')patch.ordered_at=new Date().toISOString();if(status==='received')patch.received_at=new Date().toISOString();if(status==='assigned')patch.assigned_at=new Date().toISOString();const r=await sb.from('material_requests').update(patch).eq('id',e.target.dataset.materialStatus);if(r.error)throw r.error;await loadForPage()}}catch(err){fail(err)}});
document.addEventListener('input',e=>{if(e.target.id==='customerSearch'){state.customerSearch=e.target.value;const q=state.customerSearch.toLowerCase();const list=state.customers.filter(c=>!q||[c.name,c.company,c.phone,c.email].some(v=>String(v||'').toLowerCase().includes(q)));const box=document.querySelector('.customer-grid');if(box)box.innerHTML=list.length?list.map(c=>{const ps=state.properties.filter(p=>p.customer_id===c.id),js=state.jobs.filter(j=>j.customer_id===c.id);return `<button class="customer-card" data-customer="${c.id}"><div class="row"><div><b>${esc(c.name)}</b><div class="sub">${esc(c.company||'Individual')}</div></div><span class="avatar">${esc((c.name||'?')[0].toUpperCase())}</span></div><div class="customer-contact">${c.phone?`☎ ${esc(c.phone)}`:''} ${c.email?`✉ ${esc(c.email)}`:''}</div><div class="customer-summary"><span><b>${ps.length}</b> sites</span><span><b>${js.length}</b> jobs</span><span><b>${money(js.reduce((a,j)=>a+num(j.contract_amount),0))}</b> contract</span></div></button>`}).join(''):'<div class="empty">No customers match your search.</div>';}});
document.addEventListener('dragstart',e=>{const x=e.target.closest('[data-drag-job]');if(x)e.dataTransfer.setData('text/job-id',x.dataset.dragJob)});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-drop-date]'))e.preventDefault()});
document.addEventListener('drop',async e=>{const day=e.target.closest('[data-drop-date]');if(!day)return;e.preventDefault();const id=e.dataTransfer.getData('text/job-id');if(!id)return;const j=state.jobs.find(x=>x.id===id);if(!j)return;try{const old=j.scheduled_start?new Date(j.scheduled_start):new Date();const d=new Date(day.dataset.dropDate+'T08:00:00');const end=j.scheduled_end?new Date(j.scheduled_end):new Date(d.getTime()+2*3600000);d.setHours(old.getHours()||8,old.getMinutes()||0);end.setDate(d.getDate());end.setMonth(d.getMonth());end.setFullYear(d.getFullYear());const r=await sb.from('jobs').update({scheduled_start:d.toISOString(),scheduled_end:end.toISOString(),status:j.status==='approved'?'scheduled':j.status,updated_at:new Date().toISOString()}).eq('id',id);if(r.error)throw r.error;await loadForPage()}catch(err){fail(err)}});
document.addEventListener('submit',async e=>{if(e.target.id==='loginForm'){e.preventDefault();const r=await sb.auth.signInWithPassword({email:e.target.email.value,password:e.target.password.value});if(r.error)fail(r.error)}});
document.addEventListener('click',e=>{if(e.target.id==='addEstimateLine'){const box=document.querySelector('#estimateLines');if(!box)return;const i=box.querySelectorAll('.estimate-line').length;const div=document.createElement('div');div.className='estimate-line';div.innerHTML=`<input name="desc_${i}" placeholder="Description" required><input name="qty_${i}" type="number" step=".01" value="1"><input name="price_${i}" type="number" step=".01" value="0"><input name="cost_${i}" type="number" step=".01" value="0"><input name="cat_${i}" value="Electrical">`;box.appendChild(div)}});
(async()=>{try{if(!createClient){fatal('Supabase library missing','The Supabase client did not load. Check your internet connection and reload.');return}if(!cfg?.supabaseUrl||cfg.supabaseKey?.includes('PASTE_')){fatal('Supabase configuration missing','Keep your working config.js in the GitHub repository.');return}sb=createClient(cfg.supabaseUrl,cfg.supabaseKey);const s=await sb.auth.getSession();session=s.data.session;if(session){const p=await sb.from('profiles').select('*').eq('id',session.user.id).maybeSingle();profile=p.data}history.replaceState({nolanPage:state.page},'',location.hash||'#dashboard');render();if(session)await loadForPage();sb.auth.onAuthStateChange(async(_,s2)=>{session=s2;if(s2){const p=await sb.from('profiles').select('*').eq('id',s2.user.id).maybeSingle();profile=p.data;state.history=[];state.page={type:'tab',tab:field()?'field':'dashboard'}}else profile=null;render();if(s2)await loadForPage()})}catch(e){fail(e)}})();
